      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore a consumer can buy a fair‑trade laptop.",
      "evidence": "Steps 1‑3 establish that a laptop meeting fair‑trade standards exists and is purchasable.",
